package com.lifeos.expenses.dto;import com.lifeos.expenses.*;import java.math.*;import java.time.*;public record ExpenseResponse(Long id,String description,BigDecimal amount,ExpenseCategory category,LocalDate expenseDate,LocalDateTime createdAt,LocalDateTime updatedAt){public static ExpenseResponse from(Expense e){return new ExpenseResponse(e.getId(),e.getDescription(),e.getAmount(),e.getCategory(),e.getExpenseDate(),e.getCreatedAt(),e.getUpdatedAt());}}
